        this.addAnnotation((ENamedElement)this.communicationClusterEClass, source, new String[]{"documentation", "The CommunicationCluster is the main element to describe the topological connection of communicating ECUs.\r\n\r\nA cluster describes the ensemble of ECUs, which are linked by a communication medium of arbitrary topology (bus, star, ring, ...). The nodes within the cluster share the same communication protocol, which may be event-triggered, time-triggered or a combination of both.\r\n\r\nA CommunicationCluster aggregates one or more physical channels. All physical channels that are aggregated by a communication cluster  are synchronized with each other."});
        this.addAnnotation((ENamedElement)this.communicationCycleEClass, source, new String[]{"documentation", "The communication cycle where the frame is sent."});
