        this.addAnnotation((ENamedElement)this.getCycleCounter_CycleCounter(), source, new String[]{"documentation", "The communication cycle where the frame described by this timing is sent. If a timing is given in this way the referencing cluster must specify the NUMBER-OF-CYCLES as upper bound and point of total repetition. \r\n\r\nThis value is incremented at the beginning of each new cycle, ranging from 0 to\r\n63, and is reset to 0 after a sequence of 64 cycles."});
        this.addAnnotation((ENamedElement)this.cycleRepetitionEClass, source, new String[]{"documentation", "The communication cycle where the frame is send is described by the\r\nattributes baseCycle and cycleRepetition."});
        this.addAnnotation((ENamedElement)this.cycleRepetitionEClass.getEOperations().get(0), source, new String[]{"body", "return (<%org.artop.aal.common.datatypes.IntegerDatatype%>)baseCycle.clone();"});
        this.addAnnotation((ENamedElement)this.cycleRepetitionEClass.getEOperations().get(1), source, new String[]{"body", "baseCycle.setRadix(newBaseCycle.getRadix());\nbaseCycle.setNoOfDigits(newBaseCycle.getNoOfDigits());\nsetBaseCycle(newBaseCycle.getValue());\n"});
        this.addAnnotation((ENamedElement)this.getCycleRepetition_BaseCycle(), source, new String[]{"documentation", "The first communication cycle where the frame is sent.\r\n\r\nThis value is incremented at the beginning of each new cycle, ranging from 0 to\r\n63, and is reset to 0 after a sequence of 64 cycles."});
        this.addAnnotation((ENamedElement)this.getCycleRepetition_CycleRepetition(), source, new String[]{"documentation", "The number of communication cycles (after the first cycle) whenever the frame described by this timing is sent again."});
