        this.addAnnotation((ENamedElement)this.cycleRepetitionTypeEEnum.getELiterals().get(2), source, new String[]{"documentation", "Attribute cycleRepetition value=\"4\"\r\n\r\nvalid only for FlexRay Protocol 2.1 Rev A\r\n"});
