        this.addAnnotation((ENamedElement)this.getEcuInstance_AssociatedComIPduGroups(), source, new String[]{"documentation", "With this reference it is possible to identify which ISignalIPduGroups are applicable for which CommunicationConnector/ ECU. \r\n\r\nOnly top level ISignalIPduGroups shall be referenced by an EcuInstance. If an ISignalIPduGroup contains other ISignalIPduGroups than these contained ISignalIPduGroups shall not be referenced by the EcuInstance. Contained ISignalIPduGroups are associated to an EcuInstance via the top level ISignalIPduGroup.  \r\n"});
